"use strict";
import { Contract } from "@ethersproject/contracts";
import { Interface } from "@ethersproject/abi";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useAccount } from "hooks/useAccount";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { Token } from "@uniswap/sdk-core";
import { useQuery } from "@tanstack/react-query";
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { name: "target", type: "address" },
          { name: "callData", type: "bytes" }
        ],
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { name: "blockNumber", type: "uint256" },
      { name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
const POOL_ABI = ["function token0() external view returns (address)", "function token1() external view returns (address)"];
const ERC20_ABI = [
  "function symbol() external view returns (string)",
  "function decimals() external view returns (uint8)",
  "function name() external view returns (string)"
];
export function useBatchPoolTokens(poolAddresses, chainId) {
  const account = useAccount();
  const actualChainId = chainId || account.chainId || UniverseChainId.Mainnet;
  const provider = useEthersProvider({ chainId: actualChainId });
  const { data, isLoading } = useQuery({
    queryKey: ["batch-pool-tokens", actualChainId, poolAddresses?.join(",")],
    queryFn: async () => {
      if (!poolAddresses || poolAddresses.length === 0 || !provider) {
        return /* @__PURE__ */ new Map();
      }
      const multicallContract = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
      const poolInterface = new Interface(POOL_ABI);
      const erc20Interface = new Interface(ERC20_ABI);
      const poolTokenCalls = [];
      poolAddresses.forEach((poolAddress) => {
        if (poolAddress && poolAddress !== "0x0000000000000000000000000000000000000000") {
          poolTokenCalls.push({
            target: poolAddress,
            callData: poolInterface.encodeFunctionData("token0")
          });
          poolTokenCalls.push({
            target: poolAddress,
            callData: poolInterface.encodeFunctionData("token1")
          });
        }
      });
      if (poolTokenCalls.length === 0) {
        return /* @__PURE__ */ new Map();
      }
      const [, poolTokenResults] = await multicallContract.callStatic.aggregate(poolTokenCalls);
      const poolTokenAddresses = /* @__PURE__ */ new Map();
      const uniqueTokens = /* @__PURE__ */ new Set();
      poolAddresses.forEach((poolAddress, index) => {
        if (!poolAddress || poolAddress === "0x0000000000000000000000000000000000000000") {
          return;
        }
        try {
          const baseIndex = index * 2;
          const [token0Address] = poolInterface.decodeFunctionResult("token0", poolTokenResults[baseIndex]);
          const [token1Address] = poolInterface.decodeFunctionResult("token1", poolTokenResults[baseIndex + 1]);
          poolTokenAddresses.set(poolAddress.toLowerCase(), { token0Address, token1Address });
          uniqueTokens.add(token0Address.toLowerCase());
          uniqueTokens.add(token1Address.toLowerCase());
        } catch (error) {
          console.warn(`[BATCH POOL TOKENS] Failed to decode token addresses for pool ${poolAddress}:`, error);
        }
      });
      const tokenCalls = [];
      const tokenList = Array.from(uniqueTokens);
      tokenList.forEach((tokenAddress) => {
        tokenCalls.push({
          target: tokenAddress,
          callData: erc20Interface.encodeFunctionData("decimals")
        });
        tokenCalls.push({
          target: tokenAddress,
          callData: erc20Interface.encodeFunctionData("symbol")
        });
        tokenCalls.push({
          target: tokenAddress,
          callData: erc20Interface.encodeFunctionData("name")
        });
      });
      const [, tokenResults] = await multicallContract.callStatic.aggregate(tokenCalls);
      const tokenMap = /* @__PURE__ */ new Map();
      for (let i = 0; i < tokenList.length; i++) {
        const baseIndex = i * 3;
        const address = tokenList[i];
        try {
          const [decimals] = erc20Interface.decodeFunctionResult("decimals", tokenResults[baseIndex]);
          const [symbol] = erc20Interface.decodeFunctionResult("symbol", tokenResults[baseIndex + 1]);
          const [name] = erc20Interface.decodeFunctionResult("name", tokenResults[baseIndex + 2]);
          tokenMap.set(address.toLowerCase(), new Token(actualChainId, address, decimals, symbol, name));
        } catch (error) {
          console.warn(`[BATCH POOL TOKENS] Failed to decode token metadata for ${address}:`, error);
          const knownTokens = {
            "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d": { symbol: "WETH", decimals: 18, name: "Wrapped Ether" },
            "0xb6313be1c20dc222199ec567951abc6b5b64dfd6": { symbol: "ABX", decimals: 18, name: "Aborean Token" },
            "0x698f98ab816670692fa9dd8e1486ea0fd253e996": { symbol: "USDC", decimals: 18, name: "USD Coin" }
          };
          const fallback = knownTokens[address.toLowerCase()];
          if (fallback) {
            tokenMap.set(
              address.toLowerCase(),
              new Token(actualChainId, address, fallback.decimals, fallback.symbol, fallback.name)
            );
          } else {
            tokenMap.set(address.toLowerCase(), new Token(actualChainId, address, 18, "TOKEN", "Unknown Token"));
          }
        }
      }
      const poolTokenMap = /* @__PURE__ */ new Map();
      poolTokenAddresses.forEach(({ token0Address, token1Address }, poolAddress) => {
        const token0 = tokenMap.get(token0Address.toLowerCase());
        const token1 = tokenMap.get(token1Address.toLowerCase());
        if (token0 && token1) {
          poolTokenMap.set(poolAddress.toLowerCase(), { token0, token1 });
        }
      });
      return poolTokenMap;
    },
    enabled: Boolean(poolAddresses && poolAddresses.length > 0 && provider),
    staleTime: 36e5,
    // 1 hour - pool tokens don't change
    gcTime: 864e5,
    // 24 hours - keep in cache
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false
  });
  return {
    data: data || /* @__PURE__ */ new Map(),
    isLoading
  };
}
